calls = []

def flaky(n):
    calls.append(n)
    if len(calls) < 3:
        raise TimeoutError("slow")
    return "ok"

def retry(fn, arg, attempts=3):
    for i in range(attempts):
        try:
            return fn(arg)
        except TimeoutError as e:
            last = e
            print("retry", i)
    raise last

