import json

class RateLimited(Exception):
    def __init__(self, retry_after):
        super().__init__(f"429, retry after {retry_after}s")
        self.retry_after = retry_after

SCRIPT = [
    TimeoutError("read timed out"),
    RateLimited(retry_after=5),
    '{"tool": "lookup", "args": {"id": 7}',
    '{"final": "id 7 is active"}',
    TimeoutError("read timed out"),
    TimeoutError("read timed out"),
]

def call_model(prompt, _state={"i": 0}):
    item = SCRIPT[_state["i"]]
    _state["i"] += 1
    if isinstance(item, Exception):
        raise item
    return item

sleeps = []

def sleep(seconds):
    sleeps.append(seconds)

def call_with_retry(prompt, max_attempts=4, base=1.0):
    for attempt in range(max_attempts):
        try:
            reply = call_model(prompt)
            return json.loads(reply)
        except RateLimited as e:
            delay = e.retry_after
        except TimeoutError:
            delay = base * 2 ** attempt
        except json.JSONDecodeError as e:
            return {"error": f"bad JSON from model: {e.msg}"}
        sleep(delay)
    raise RuntimeError(f"gave up after {max_attempts} attempts")

print(call_with_retry("status of 7?"))
print(call_with_retry("again?"))
print(sleeps)
print(call_with_retry("third?", max_attempts=2))
